effects.vanillaTargetSemantic:
Native hook behavior: public override bool TryModifyRewards(Player player, List<Reward> rewards, AbstractRoom? room)
	{
		if (player != base.Owner)
		{
			return false;
		}
		if (room == null)
		{
			return false;
		}
		if (!room.RoomType.IsCombatRoom())
		{
			return false;
		}
		if (room.RoomType == RoomType.Boss && player.RunState.CurrentActIndex >= player.RunState.Acts.Count - 1)
		{
			return false;
		}
		rewards.Add(new GoldReward(base.DynamicVars.Gold.IntValue, player));
		return true;
	}

